package com.grocery.entity; import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.*; @Entity @Data @NoArgsConstructor @AllArgsConstructor public class GroceryOrder{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private LocalDateTime orderDate; private Double totalPrice; @ManyToOne private Customer customer; @ManyToMany private List<GroceryItem> items; }